        const L = r2.range(70, 130), turns = r2.range(2.6, 3.6);
        const m = new THREE.Mesh(cloudGeo(L * 0.8, turns - 0.4), cloudMat);
        const az = 0.55 + i * 0.33 + r2.range(-0.1, 0.1), dist = r2.range(520, 900);
