        m.rotation.order = 'YXZ'; m.rotation.set(0, r2.range(-0.8, 0.8) * Math.PI / 0.8, r2.range(-0.3, 0.3) * 0.5); m.userData = { ph: r2() * TAU, x0: m.position.x, sp: r2.range(1.5, 4) };
