    // entered in. Uniform values only; at u 0 (and through the previous portal) the look is the arrival's.
    const SU = style.uniforms, base = { halo: SU.cHalo.value.clone(), sky: SU.cSkyLo.value.clone(), lit: SU.cLitB.value.clone(), sun: SU.cSunC.value.clone(), k: SU.uSkyK.value.clone() };
    const duskK = hour === 'golden' ? 1 : hour === 'dawn' ? 0.6 : hour === 'day' ? 0.45 : 0.3, sinkDeg = hour === 'golden' ? 2.4 : hour === 'dawn' ? -2.5 : hour === 'day' ? 5 : 1.5;
